261: impl VmMapping {
262:     /// Handles a page fault.
263:     pub(super) fn handle_page_fault(
264:         &self,
265:         vm_space: &VmSpace,
266:         page_fault_info: &PageFaultInfo,
267:         rss_delta: &mut RssDelta,
268:     ) -> Result<()> {
269:         if !self.perms.contains(page_fault_info.required_perms) {
270:             trace!(
271:                 "self.perms {:?}, page_fault_info.required_perms {:?}, self.range {:?}",
272:                 self.perms,
273:                 page_fault_info.required_perms,
274:                 self.range()
275:             );
276:             return_errno_with_message!(Errno::EACCES, "perm check fails");
277:         }
278: 
279:         let page_aligned_addr = page_fault_info.address.align_down(PAGE_SIZE);
280:         let is_write = page_fault_info.required_perms.contains(VmPerms::WRITE);
281: 
282:         if !is_write
283:             && matches!(&self.mapped_mem, MappedMemory::Vmo(_))
284:             && self.handle_page_faults_around
285:         {
286:             let res = self.handle_page_faults_around(
287:                 vm_space,
288:                 page_aligned_addr,
289:                 page_fault_info.required_perms,
290:                 rss_delta,
291:             );
292: 
293:             // Errors caused by the "around" pages should be ignored, so here we
294:             // only return the error if the faulting page is still not mapped.
295:             if res.is_err() {
296:                 let preempt_guard = disable_preempt();
297:                 let mut cursor = vm_space.cursor(
298:                     &preempt_guard,
299:                     &(page_aligned_addr..page_aligned_addr + PAGE_SIZE),
300:                 )?;
301:                 if let (_, Some(_)) = cursor.query().unwrap() {
302:                     return Ok(());
303:                 }
304:             }
305: 
306:             return res;
307:         }
308: 
309:         self.handle_single_page_fault(
310:             vm_space,
311:             page_aligned_addr,
312:             page_fault_info.required_perms,
313:             rss_delta,
314:         )
315:     }
316: 
317:     fn handle_single_page_fault(
318:         &self,
319:         vm_space: &VmSpace,
320:         page_aligned_addr: Vaddr,
321:         required_perms: VmPerms,
322:         rss_delta: &mut RssDelta,
323:     ) -> Result<()> {
324:         'retry: loop {
325:             let preempt_guard = disable_preempt();
326:             let mut cursor = vm_space.cursor_mut(
327:                 &preempt_guard,
328:                 &(page_aligned_addr..page_aligned_addr + PAGE_SIZE),
329:             )?;
330: 
331:             let (va, item) = cursor.query().unwrap();
332:             let is_write = required_perms.contains(VmPerms::WRITE);
333:             match item {
334:                 Some(VmQueriedItem::MappedRam { frame, mut prop }) => {
335:                     if VmPerms::from(prop.flags).contains(required_perms) {
336:                         // The page fault is already handled maybe by other threads.
337:                         // Just flush the TLB and return.
338:                         TlbFlushOp::for_range(va).perform_on_current();
339:                         return Ok(());
340:                     }
341:                     assert!(is_write);
342:                     // Perform COW if it is a write access to a shared mapping.
343: 
344:                     // Skip if the page fault is already handled.
345:                     if prop.flags.contains(PageFlags::W) {
346:                         return Ok(());
347:                     }
348: 
349:                     // If the forked child or parent immediately unmaps the page after
350:                     // the fork without accessing it, we are the only reference to the
351:                     // frame. We can directly map the frame as writable without
352:                     // copying. In this case, the reference count of the frame is 2 (
353:                     // one for the mapping and one for the frame handle itself).
354:                     let only_reference = frame.reference_count() == 2;
355: 
356:                     let new_flags = PageFlags::W | PageFlags::ACCESSED | PageFlags::DIRTY;
357: 
358:                     if self.is_shared || only_reference {
359:                         cursor.protect_next(PAGE_SIZE, |flags, _cache| {
360:                             *flags |= new_flags;
361:                         });
362:                         cursor.flusher().issue_tlb_flush(TlbFlushOp::for_range(va));
363:                         cursor.flusher().dispatch_tlb_flush();
364:                     } else {
365:                         let new_frame = duplicate_frame(&frame)?;
366:                         prop.flags |= new_flags;
367:                         cursor.map(new_frame.into(), prop);
368:                         rss_delta.add(self.rss_type(), 1);
369:                     }
370:                     cursor.flusher().sync_tlb_flush();
371:                 }
372:                 Some(VmQueriedItem::MappedIoMem { .. }) => {
373:                     // The page of I/O memory is populated when the memory
374:                     // mapping is created.
375:                     return_errno_with_message!(
376:                         Errno::EFAULT,
377:                         "device memory page faults cannot be resolved"
378:                     );
379:                 }
380:                 None => {
381:                     // Map a new frame to the page fault address.
382:                     let (frame, is_readonly) = match self.prepare_page(page_aligned_addr, is_write)
383:                     {
384:                         Ok((frame, is_readonly)) => (frame, is_readonly),
385:                         Err(VmoCommitError::Err(e)) => return Err(e),
386:                         Err(VmoCommitError::NeedIo(index)) => {
387:                             drop(cursor);
388:                             drop(preempt_guard);
389:                             self.vmo().unwrap().commit_on(index, CommitFlags::empty())?;
390:                             continue 'retry;
391:                         }
392:                     };
393: 
394:                     let vm_perms = {
395:                         let mut perms = self.perms;
396:                         if is_readonly {
397:                             // COW pages are forced to be read-only.
398:                             perms -= VmPerms::WRITE;
399:                         }
400:                         perms
401:                     };
402: 
403:                     let mut page_flags = vm_perms.into();
404:                     page_flags |= PageFlags::ACCESSED;
405:                     if is_write {
406:                         page_flags |= PageFlags::DIRTY;
407:                     }
408:                     let map_prop = PageProperty::new_user(page_flags, CachePolicy::Writeback);
409: 
410:                     cursor.map(frame, map_prop);
411:                     rss_delta.add(self.rss_type(), 1);
412:                 }
413:             }
414:             break 'retry;
415:         }
416: 
417:         Ok(())
418:     }
