420:     fn prepare_page(
421:         &self,
422:         page_aligned_addr: Vaddr,
423:         write: bool,
424:     ) -> core::result::Result<(UFrame, bool), VmoCommitError> {
425:         let mut is_readonly = false;
426: 
427:         let vmo = match &self.mapped_mem {
428:             MappedMemory::Vmo(vmo) => vmo,
429:             MappedMemory::Anonymous => {
430:                 // Anonymous mapping. Allocate a new frame.
431:                 return Ok((FrameAllocOptions::new().alloc_frame()?.into(), is_readonly));
432:             }
433:             MappedMemory::Device => {
434:                 // Device memory is populated when the memory mapping is created.
435:                 return Err(VmoCommitError::Err(Error::with_message(
436:                     Errno::EFAULT,
437:                     "device memory page faults cannot be resolved",
438:                 )));
439:             }
440:         };
441: 
442:         let page_offset = page_aligned_addr - self.map_to_addr;
443:         if !self.is_shared && page_offset >= vmo.valid_size() {
444:             // The page index is outside the VMO. This is only allowed in private mapping.
445:             return Ok((FrameAllocOptions::new().alloc_frame()?.into(), is_readonly));
446:         }
447: 
448:         let page = vmo.get_committed_frame(page_offset)?;
449:         if !self.is_shared && write {
450:             // Write access to private VMO-backed mapping. Performs COW directly.
451:             Ok((duplicate_frame(&page)?.into(), is_readonly))
452:         } else {
453:             // Operations to shared mapping or read access to private VMO-backed mapping.
454:             // If read access to private VMO-backed mapping triggers a page fault,
455:             // the map should be readonly. If user next tries to write to the frame,
456:             // another page fault will be triggered which will performs a COW (Copy-On-Write).
457:             is_readonly = !self.is_shared;
458:             Ok((page, is_readonly))
459:         }
460:     }
