462:     /// Handles a page fault and maps additional surrounding pages.
463:     fn handle_page_faults_around(
464:         &self,
465:         vm_space: &VmSpace,
466:         page_aligned_addr: Vaddr,
467:         required_perms: VmPerms,
468:         mut rss_delta: &mut RssDelta,
469:     ) -> Result<()> {
470:         const SURROUNDING_PAGE_NUM: usize = 16;
471:         const SURROUNDING_PAGE_ADDR_MASK: usize = !(SURROUNDING_PAGE_NUM * PAGE_SIZE - 1);
472: 
473:         let vmo = self.vmo().unwrap();
474:         let around_page_addr = page_aligned_addr & SURROUNDING_PAGE_ADDR_MASK;
475:         let size = min(vmo.valid_size(), self.map_size.get());
476:         let mut start_addr = max(around_page_addr, self.map_to_addr);
477:         let end_addr = min(
478:             start_addr + SURROUNDING_PAGE_NUM * PAGE_SIZE,
479:             self.map_to_addr + size,
480:         );
481: 
482:         // The page fault address falls outside the VMO bounds.
483:         // Only a single page fault is handled in this situation.
484:         if end_addr <= page_aligned_addr {
485:             return self.handle_single_page_fault(
486:                 vm_space,
487:                 page_aligned_addr,
488:                 required_perms,
489:                 rss_delta,
490:             );
491:         }
492: 
493:         let vm_perms = self.perms - VmPerms::WRITE;
494: 
495:         'retry: loop {
496:             let preempt_guard = disable_preempt();
497:             let mut cursor = vm_space.cursor_mut(&preempt_guard, &(start_addr..end_addr))?;
498: 
499:             let rss_delta_ref = &mut rss_delta;
500:             let operate =
501:                 move |commit_fn: &mut dyn FnMut()
502:                     -> core::result::Result<UFrame, VmoCommitError>| {
503:                     if let (_, None) = cursor.query().unwrap() {
504:                         // We regard all the surrounding pages as accessed, no matter
505:                         // if it is really so. Then the hardware won't bother to update
506:                         // the accessed bit of the page table on following accesses.
507:                         let page_flags = PageFlags::from(vm_perms) | PageFlags::ACCESSED;
508:                         let page_prop = PageProperty::new_user(page_flags, CachePolicy::Writeback);
509:                         let frame = commit_fn()?;
510:                         cursor.map(frame, page_prop);
511:                         rss_delta_ref.add(self.rss_type(), 1);
512:                     } else {
513:                         let next_addr = cursor.virt_addr() + PAGE_SIZE;
514:                         if next_addr < end_addr {
515:                             let _ = cursor.jump(next_addr);
516:                         }
517:                     }
518:                     Ok(())
519:                 };
520:

520: 
521:             let start_offset = start_addr - self.map_to_addr;
522:             let end_offset = end_addr - self.map_to_addr;
523:             match vmo.try_operate_on_range(&(start_offset..end_offset), operate) {
524:                 Ok(_) => return Ok(()),
525:                 Err(VmoCommitError::NeedIo(index)) => {
526:                     drop(preempt_guard);
527:                     vmo.commit_on(index, CommitFlags::empty())?;
528:                     start_addr = (index * PAGE_SIZE - vmo.offset()) + self.map_to_addr;
529:                     continue 'retry;
530:                 }
531:                 Err(VmoCommitError::Err(e)) => return Err(e),
532:             }
533:         }
534:     }
535: }
