539: impl VmMapping {
540:     /// Enlarges the mapping by `extra_size` bytes to the high end.
541:     pub fn enlarge(self, extra_size: usize) -> Self {
542:         Self {
543:             map_size: NonZeroUsize::new(self.map_size.get() + extra_size).unwrap(),
544:             ..self
545:         }
546:     }
547: 
548:     /// Splits the mapping at the specified address.
549:     ///
550:     /// The address must be within the mapping and page-aligned. The address
551:     /// must not be either the start or the end of the mapping.
552:     pub fn split(self, at: Vaddr) -> Result<(Self, Self)> {
553:         debug_assert!(self.map_to_addr < at && at < self.map_end());
554:         debug_assert!(at.is_multiple_of(PAGE_SIZE));
555: 
556:         let (l_mapped_mem, r_mapped_mem) = match self.mapped_mem {
557:             MappedMemory::Vmo(vmo) => {
558:                 let at_offset = vmo.offset() + (at - self.map_to_addr);
559:                 let r_mapped_vmo = vmo.dup_at_offset(at_offset);
560:                 (MappedMemory::Vmo(vmo), MappedMemory::Vmo(r_mapped_vmo))
561:             }
562:             MappedMemory::Anonymous => {
563:                 // For anonymous mappings, we create new anonymous mappings for the split parts
564:                 (MappedMemory::Anonymous, MappedMemory::Anonymous)
565:             }
566:             MappedMemory::Device => {
567:                 // For device memory mappings, we create new device memory mappings for the split parts
568:                 (MappedMemory::Device, MappedMemory::Device)
569:             }
570:         };
571: 
572:         let left_size = at - self.map_to_addr;
573:         let right_size = self.map_size.get() - left_size;
574:         let left = Self {
575:             map_to_addr: self.map_to_addr,
576:             map_size: NonZeroUsize::new(left_size).unwrap(),
577:             mapped_mem: l_mapped_mem,
578:             inode: self.inode.clone(),
579:             ..self
580:         };
581:         let right = Self {
582:             map_to_addr: at,
583:             map_size: NonZeroUsize::new(right_size).unwrap(),
584:             mapped_mem: r_mapped_mem,
585:             ..self
586:         };
587: 
588:         Ok((left, right))
589:     }
590: 
591:     /// Splits the mapping at the specified address.
592:     ///
593:     /// There are four conditions:
594:     /// 1. |-outside `range`-| + |------------within `range`------------|
595:     /// 2. |------------within `range`------------| + |-outside `range`-|
596:     /// 3. |-outside `range`-| + |-within `range`-| + |-outside `range`-|
597:     /// 4. |----------------------within `range` -----------------------|
598:     ///
599:     /// Returns (left outside, within, right outside) if successful.
600:     ///
601:     /// # Panics
602:     ///
603:     /// Panics if the mapping does not contain the range, or if the start or
604:     /// end of the range is not page-aligned.
605:     pub fn split_range(self, range: &Range<Vaddr>) -> (Option<Self>, Self, Option<Self>) {
606:         let mapping_range = self.range();
607:         if range.start <= mapping_range.start && mapping_range.end <= range.end {
608:             // Condition 4.
609:             (None, self, None)
610:         } else if mapping_range.start < range.start {
611:             let (left, within) = self.split(range.start).unwrap();
612:             if range.end < mapping_range.end {
613:                 // Condition 3.
614:                 let (within, right) = within.split(range.end).unwrap();
615:                 (Some(left), within, Some(right))
616:             } else {
617:                 // Condition 1.
618:                 (Some(left), within, None)
619:             }
620:         } else if mapping_range.contains(&range.end) {
621:             // Condition 2.
622:             let (within, right) = self.split(range.end).unwrap();
623:             (None, within, Some(right))
624:         } else {
625:             panic!("The mapping does not contain the splitting range");
626:         }
627:     }
628: 
629:     /// Attempts to merge `self` with the given `vm_mapping` if they are
630:     /// adjacent and compatible.
631:     ///
632:     /// Two mappings are considered *adjacent* if the end address of `self`
633:     /// equals to the start address of `vm_mapping`, or vice versa.
634:     ///
635:     /// Two mappings are considered *compatible* if all of the following
636:     /// conditions are met:
637:     /// - They have the same access permissions.
638:     /// - They are both anonymous or share the same backing file.
639:     /// - Their file offsets are contiguous if file-backed.
640:     /// - Other attributes (e.g., shared/private flags, whether need to handle
641:     ///   page faults around, etc.) must also match.
642:     ///
643:     /// This method returns:
644:     /// - the merged mapping along with the address of the mapping
645:     ///   to be removed if successful.
646:     /// - the original `self` and a `None` otherwise.
647:     pub fn try_merge_with(self, vm_mapping: &VmMapping) -> (Self, Option<Vaddr>) {
648:         debug_assert!(!is_intersected(&self.range(), &vm_mapping.range()));
649: 
650:         let (left, right) = if self.map_to_addr < vm_mapping.map_to_addr {
651:             (&self, vm_mapping)
652:         } else {
653:             (vm_mapping, &self)
654:         };
655: 
656:         if let Some(merged) = try_merge(left, right) {
657:             (merged, Some(vm_mapping.map_to_addr))
658:         } else {
659:             (self, None)
660:         }
661:     }
662: }
